#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/swift/tasks/code-format-swift-format.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Check or format the Swift files with swift-format"
# MISE hide=true
# MISE tools={uv="latest", python="3.14"}
# USAGE flag "--all" help="format every file of the repository, not only the uncommitted files"
# USAGE flag "--debug" help="accepted for the code:format contract"
# USAGE flag "--fix" help="apply fixes"
# USAGE arg "[files]" var=#true help="the files to format; only the .swift files are used; the default is the uncommitted files"
# FILES include="*.swift" exclude="*.generated.swift .build/** .swiftpm/** **/Derived/** **/DerivedData/**"

import os
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
import helpers  # noqa: E402

# Shipped with the swift tool. swift-format comes with the Swift toolchain of
# the host, not from mise. Without it, the task does not apply and prints
# nothing.
try:
  found = (
    subprocess.run(
      ["swift", "format", "--version"], check=False, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL
    ).returncode
    == 0
  )
except OSError:
  found = False
if not found:
  sys.exit(0)
os.chdir(os.environ["MISE_PROJECT_ROOT"])

# code:format passes its flags and files to each code:format:* task. The list
# comes from gate_files (the # FILES header above). An empty list: nothing
# to do.
args = [f"--{flag}" for flag in ("all", "debug", "fix") if os.environ.get(f"usage_{flag}") == "true"]
listing = helpers.gate_files(__file__, *args, *helpers.usage_files())
try:
  if os.path.getsize(listing) == 0:
    sys.exit(0)

  helpers.print_header("Formatting the Swift files with swift-format ...")
  # Without --fix, the check is the strict lint: format has no mode that only
  # reports. It also reports the rules that format cannot fix. xargs gives the
  # list to the tool, as each gate does.
  if os.environ.get("usage_fix") == "true":
    command = ["swift", "format", "format", "--in-place", "--parallel", "--configuration", ".config/swift-format.json"]
  else:
    command = ["swift", "format", "lint", "--strict", "--parallel", "--configuration", ".config/swift-format.json"]
  with open(listing, "rb") as f:
    files = f.read().replace(b"\n", b"\0")
  result = subprocess.run(["xargs", "-0", *command], input=files, check=False)
  sys.exit(result.returncode)
finally:
  os.remove(listing)
